CREATE TABLE IF NOT EXISTS counts(id text PRIMARY KEY,org_id text NOT NULL REFERENCES organizations(id),location_id text NOT NULL REFERENCES locations(id),expected_codes jsonb NOT NULL,status text NOT NULL DEFAULT 'observing',version integer NOT NULL DEFAULT 1,created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS count_observations(id text PRIMARY KEY,org_id text NOT NULL REFERENCES organizations(id),count_id text NOT NULL REFERENCES counts(id),box_code text NOT NULL,actor_id text NOT NULL REFERENCES users(id),created_at timestamptz NOT NULL DEFAULT now(),UNIQUE(count_id,box_code));
